use super::*;
use novel_storage::{Project,ProjectDataSnapshot,UniverseCatalogue,UniverseCatalogueView,UniverseMembership,UniverseNovel,UniverseSeries};
fn fixture()->(UniverseCatalogueSnapshot,UniverseNotesSnapshot){let projects=vec![Project{id:"world".into(),title:"العالم 世界".into(),created_at:"now".into()},Project{id:"novel".into(),title:"مِ 𠀀".into(),created_at:"now".into()},Project{id:"solo".into(),title:"Independent".into(),created_at:"now".into()}];let source=UniverseCatalogueView{project_id:"world".into(),title:projects[0].title.clone(),catalogue_revision_id:Some("catalogue-revision".into()),catalogue:Some(UniverseCatalogue{schema_version:1,series:vec![UniverseSeries{id:"series".into(),title:"سلسلة e\u{301}".into()}],novels:vec![UniverseNovel{project_id:"novel".into(),series_id:Some("series".into())},UniverseNovel{project_id:"missing".into(),series_id:None}]}),unavailable:None};let member=UniverseMembership{project_id:"novel".into(),universe_id:Some("world".into()),series_id:Some("series".into()),status:"member".into(),reason:None};let standalone=UniverseMembership{project_id:"solo".into(),universe_id:None,series_id:None,status:"unassigned".into(),reason:None};let root=UniverseMembership{project_id:"world".into(),universe_id:None,series_id:None,status:"universe".into(),reason:None};let notes=UniverseNotesSnapshot{project_id:"novel".into(),membership:member.clone(),universe:Some(source.clone()),planning:Some(ProjectDataSnapshot{revision_id:"world-revision".into(),payload:json!({"schemaVersion":1,"records":[{"id":"person","name":"نور 明 e\u{301}","kind":"character","notes":"مِ 👩🏽‍🚀 𠀀 \u{e000}","aliases":["Exact alias"],"values":{"visible":"حقل 中文","hidden":"SECRET HIDDEN","opaque":{"kind":"scene","id":"not-canon"}}}],"fields":[{"id":"visible","label":"Field","recordKind":"character","kind":"text","hidden":false,"options":[]},{"id":"hidden","label":"Secret","recordKind":"character","kind":"text","hidden":true,"options":[]},{"id":"opaque","label":"Opaque","recordKind":"character","kind":"links","hidden":false,"options":[]}],"facts":[{"id":"fact","subjectId":"person","observerId":null,"eventId":null,"untilEventId":null,"property":"Fact","value":"يَكشف e\u{301}","confirmed":false,"status":"rumor","source":"Authored shared source"}]})}),unavailable:None};(UniverseCatalogueSnapshot{projects,universes:vec![source],memberships:vec![member,standalone,root]},notes)}
#[test]fn grouped_selector_preserves_novel_identity_and_disables_headers_and_missing_projects(){let (snapshot,_)=fixture();let before=snapshot.clone();let rows=selector_rows(&snapshot);assert_eq!(rows.iter().filter_map(|r|r.project_id.as_deref()).collect::<HashSet<_>>(),HashSet::from(["novel","solo","world"]));assert!(rows.iter().any(|r|r.project_id.is_none()&&r.label=="Universe · العالم 世界"));assert!(rows.iter().any(|r|r.project_id.is_none()&&r.label.contains("سلسلة e\u{301}")));assert!(rows.iter().any(|r|r.project_id.is_none()&&r.label.contains("Unavailable novel")));assert_eq!(rows.iter().find(|r|r.project_id.as_deref()==Some("novel")).unwrap().label,"    مِ 𠀀");assert_eq!(snapshot,before);}
#[test]fn conflicted_membership_keeps_local_project_available_without_a_group(){let (mut snapshot,_)=fixture();snapshot.memberships[0].status="conflicted".into();snapshot.memberships[0].universe_id=None;let rows=selector_rows(&snapshot);let novel=rows.iter().filter(|r|r.project_id.as_deref()==Some("novel")).collect::<Vec<_>>();assert_eq!(novel.len(),1);assert!(novel[0].label.contains("Shared membership unavailable"));snapshot.universes[0].unavailable=Some("conflict".into());snapshot.universes[0].catalogue=None;assert!(!selector_rows(&snapshot).iter().any(|r|r.project_id.is_none()&&r.label.starts_with("Universe ·")));}
#[test]fn shared_notes_label_exact_sources_and_keep_rumors_separate_from_approved_canon(){let (_,notes)=fixture();let before=notes.clone();let view=notes_text(&notes,"");for text in ["العالم 世界","سلسلة e\u{301}","catalogue-revision","world-revision","نور 明 e\u{301}","مِ 👩🏽‍🚀 𠀀 \u{e000}","حقل 中文","rumor","Authored shared source"]{assert!(view.contains(text),"{text}");}assert!(!view.contains("SECRET HIDDEN"));assert!(!view.contains("not-canon"));assert!(!view.contains("Approved fact"));assert!(notes_text(&notes,"Exact alias").contains("نور 明"));assert!(!notes_text(&notes,"no match").contains("نور 明"));assert_eq!(notes,before);}
#[test]fn unavailable_sources_never_show_retained_stale_notes(){let (_,mut notes)=fixture();notes.unavailable=Some("Conflict: competing universe planning".into());let view=notes_text(&notes,"");assert!(view.contains("Unavailable"));assert!(!view.contains("نور 明"));assert!(!view.contains("world-revision"));notes.unavailable=None;notes.universe.as_mut().unwrap().catalogue=None;assert!(!notes_text(&notes,"").contains("نور 明"));}
#[test]fn mismatched_shared_source_or_membership_never_displays_records(){let (_,mut notes)=fixture();notes.membership.universe_id=Some("other-world".into());assert!(!notes_text(&notes,"").contains("نور 明"));let (_,mut notes)=fixture();notes.membership.series_id=None;assert!(!notes_text(&notes,"").contains("نور 明"));let (_,mut notes)=fixture();notes.membership.project_id="other-novel".into();assert!(!notes_text(&notes,"").contains("نور 明"));}
#[test]fn shared_notes_excerpt_and_work_limits_do_not_mutate_source(){let (_,mut notes)=fixture();notes.planning.as_mut().unwrap().payload["records"][0]["notes"]=json!("𠀀".repeat(2_001));let original=notes.clone();let view=notes_text(&notes,"");assert!(view.contains(&format!("{}…","𠀀".repeat(2_000))));assert!(!view.contains(&"𠀀".repeat(2_001)));let record=notes.planning.as_ref().unwrap().payload["records"][0].clone();notes.planning.as_mut().unwrap().payload["records"]=json!(vec![record;101]);assert!(notes_text(&notes,"").contains("limit reached"));assert_eq!(original.planning.unwrap().payload["records"][0]["notes"],"𠀀".repeat(2_001));}

/// Root calls this in its serialized GTK harness after workers are rebuilt.
/// The existing scene-reference helper qualifies follow/pin/detach semantics;
/// this fixture adds the checked shared source, filter, conflict and refresh.
pub(crate) fn run(binaries:&Path){
    let directory=tempfile::tempdir().unwrap();let data=directory.path().join("universe-data");let cache=directory.path().join("universe-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(companion),&data,true).unwrap();let root=rpc(&client,"create_universe",json!({"title":"العالم 世界"}));let uid=root["id"].as_str().unwrap();let catalogue=rpc(&client,"load_project_data",json!({"projectId":uid,"kind":"universeCatalogue"}));let catalogue=rpc(&client,"save_project_data",json!({"projectId":uid,"kind":"universeCatalogue","parent":catalogue["revisionId"],"payload":{"schemaVersion":1,"series":[{"id":"series","title":"سلسلة e\u{301}"}],"novels":[]}}));let novel=rpc(&client,"create_universe_novel",json!({"universeId":uid,"seriesId":"series","title":"Novel 中文","parent":catalogue["revisionId"]}));let pid=novel["project"]["id"].as_str().unwrap();let sid=novel["scene"]["id"].as_str().unwrap();let original=rpc(&client,"load_scene",json!({"sceneId":sid}));let (_,template)=fixture();let mut payload=crate::tools::initial("planning");for key in ["records","fields","facts"]{payload[key]=template.planning.as_ref().unwrap().payload[key].clone();}payload["fields"].as_array_mut().unwrap().pop();payload["records"][0]["values"].as_object_mut().unwrap().remove("opaque");let world=rpc(&client,"save_project_data",json!({"projectId":uid,"kind":"planning","parent":null,"payload":payload}));let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||!a.pid.borrow().is_empty()&&!a.loading.get());a.switch_project(pid.into());wait(||a.active.borrow().as_ref().is_some_and(|p|p.scene_id==sid&&p.open.get()&&p.pending.get()==0));check_installed_selector(&a,pid,uid,sid,&original);a.scene_references();wait(||a.current_widget().as_ref().is_some_and(|w|all_text(w).contains("Story occurrence events")&&all_text(w).contains("World notes revision")));let references=a.current_widget().unwrap();assert!(all_text(&references).contains("مِ 👩🏽‍🚀 𠀀 \u{e000}"));assert!(!find_view(&references).unwrap().is_editable());let world_filter=find_reference_filter(&references).unwrap();world_filter.set_text("no match");assert!(!all_text(&references).contains("نور 明"));assert!(all_text(&references).contains("Story occurrence events"));world_filter.set_text("");assert!(all_text(&references).contains("نور 明"));a.universe_world_notes();wait(||a.current_widget().as_ref().is_some_and(|w|all_text(w).contains("World notes revision")));let widget=a.current_widget().unwrap();assert!(all_text(&widget).contains("مِ 👩🏽‍🚀 𠀀 \u{e000}"));assert!(all_text(&widget).contains(world["revisionId"].as_str().unwrap()));let filter=find_filter(&widget).unwrap();filter.set_text("no match");assert!(!all_text(&widget).contains("نور 明"));filter.set_text("Exact alias");assert!(all_text(&widget).contains("نور 明"));assert!(find_view(&widget).unwrap().is_editable()==false);assert!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})).is_null());assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),original);
    a.detach_current();let child=desk::WINDOWS.with(|windows|windows.borrow().last().unwrap().clone());assert!(!Rc::ptr_eq(&child,&a));assert_eq!(child.current_widget(),Some(widget.clone()));a.close();wait(||a.desk.is_closed());filter.set_text("");assert!(all_text(&widget).contains("نور 明"));let refresh=find_button(&widget,"Refresh saved World notes").unwrap();let mut changed=payload.clone();changed["records"][0]["notes"]=json!("New saved shared notes مِ 中文");rpc(&a.client,"save_project_data",json!({"projectId":uid,"kind":"planning","parent":world["revisionId"],"payload":changed}));refresh.clicked();wait(||all_text(&widget).contains("New saved shared notes"));
    let peer_data=directory.path().join("universe-peer");std::fs::create_dir_all(&peer_data).unwrap();let peer=Process::start(&binaries.join(companion),&peer_data,true).unwrap();let remote=rpc(&child.client,"sync_cursor",json!({}));let local=rpc(&peer,"sync_cursor",json!({}));let revisions=rpc(&child.client,"pull_revisions",json!({"projectId":uid,"cursor":{"epoch":remote["epoch"],"sequence":0},"limit":100}));rpc(&peer,"ingest_revisions",json!({"projectId":uid,"expectedEpoch":local["epoch"],"remoteEpoch":remote["epoch"],"manifest":rpc(&child.client,"open_project",json!({"projectId":uid})),"revisions":revisions["revisions"]}));let shared=rpc(&child.client,"load_project_data",json!({"projectId":uid,"kind":"planning"}));let mut primary=shared["payload"].clone();primary["records"][0]["notes"]=json!("Primary competing World notes");let mut secondary=shared["payload"].clone();secondary["records"][0]["notes"]=json!("Peer competing World notes");rpc(&child.client,"save_project_data",json!({"projectId":uid,"kind":"planning","payload":primary,"parent":shared["revisionId"]}));rpc(&peer,"save_project_data",json!({"projectId":uid,"kind":"planning","payload":secondary,"parent":shared["revisionId"]}));let remote=rpc(&peer,"sync_cursor",json!({}));let local=rpc(&child.client,"sync_cursor",json!({}));let revisions=rpc(&peer,"pull_revisions",json!({"projectId":uid,"cursor":{"epoch":remote["epoch"],"sequence":0},"limit":100}));rpc(&child.client,"ingest_revisions",json!({"projectId":uid,"expectedEpoch":local["epoch"],"remoteEpoch":remote["epoch"],"manifest":rpc(&peer,"open_project",json!({"projectId":uid})),"revisions":revisions["revisions"]}));let marker=rpc(&child.client,"sync_cursor",json!({}));refresh.clicked();wait(||all_text(&widget).contains("competing planning"));assert!(!all_text(&widget).contains("Primary competing World notes"));assert!(!all_text(&widget).contains("Peer competing World notes"));assert!(!all_text(&widget).contains("New saved shared notes"));assert_eq!(rpc(&child.client,"load_scene",json!({"sceneId":sid})),original);assert_eq!(rpc(&child.client,"sync_cursor",json!({})),marker);refresh.clicked();child.close();wait(||child.desk.is_closed());pump();assert_eq!(desk::WINDOWS.with(|w|w.borrow().len()),0);peer.stop();
}

/// Use the installed dropdown model and its real cell-data callbacks. Programmatic
/// activation additionally exercises the defensive changed-signal restore path;
/// this does not claim a physical mouse/keyboard popup interaction.
fn check_installed_selector(a:&Rc<Workspace>,pid:&str,uid:&str,sid:&str,original:&Value){
    let current=a.current_widget();let generation=a.desk.generation.get();let marker=rpc(&a.client,"sync_cursor",json!({}));
    let refreshed=Rc::new(Cell::new(false));let out=refreshed.clone();let wanted=pid.to_owned();let handler=a.projects.connect_changed(move|combo|{if combo.active_id().as_deref()==Some(wanted.as_str()){out.set(true);}});
    a.refresh_projects(Some(pid.into()));wait(||refreshed.get());a.projects.disconnect(handler);
    assert_eq!(a.projects.active_id().as_deref(),Some(pid));assert_eq!(a.pid.borrow().as_str(),pid);assert_eq!(a.current_widget(),current);assert_eq!(a.desk.generation.get(),generation);
    let model=a.projects.model().unwrap();let snapshot:UniverseCatalogueSnapshot=serde_json::from_value(rpc(&a.client,"universe_catalogue_snapshot",json!({}))).unwrap();let expected=selector_rows(&snapshot);assert_eq!(model.iter_n_children(None) as usize,expected.len());
    let area=gtk::prelude::CellLayoutExt::area(&a.projects).unwrap();let cells=a.projects.cells();assert!(!cells.is_empty());let mut saw_universe=false;let mut saw_series=false;let mut saw_novel=false;let mut saw_source=false;
    for (position,expected) in expected.iter().enumerate(){let iter=model.iter_nth_child(None,position as i32).unwrap();let label=model.value(&iter,0).get::<String>().unwrap();let identity=model.value(&iter,1).get::<Option<String>>().unwrap();assert_eq!(label,expected.label);assert_eq!(identity,expected.project_id);
        area.apply_attributes(&model,&iter,false,false);assert!(cells.iter().all(|cell|cell.is_sensitive()==identity.is_some()),"row {label} must use the actual installed sensitivity callback");
        if identity.is_none(){saw_universe|=label=="Universe · العالم 世界";saw_series|=label=="  Series · سلسلة e\u{301}";a.projects.set_active(Some(position as u32));assert_eq!(a.projects.active_id().as_deref(),Some(pid));assert_eq!(a.pid.borrow().as_str(),pid);assert_eq!(a.current_widget(),current);assert_eq!(a.desk.generation.get(),generation);assert!(!a.desk.busy.get());}
        else if identity.as_deref()==Some(pid){saw_novel=true;assert_eq!(label,"    Novel 中文");}
        else if identity.as_deref()==Some(uid){saw_source=true;assert_eq!(label,"العالم 世界");}
    }
    assert!(saw_universe&&saw_series&&saw_novel&&saw_source);let active=a.projects.active_iter().unwrap();area.apply_attributes(&model,&active,false,false);assert!(cells.iter().all(|cell|cell.is_sensitive()));assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),*original);
    let source:UniverseNotesSnapshot=serde_json::from_value(rpc(&a.client,"universe_notes_snapshot",json!({"projectId":pid}))).unwrap();assert_eq!(source.universe.as_ref().unwrap().project_id,uid);assert_eq!(source.membership.series_id.as_deref(),Some("series"));assert!(source.unavailable.is_none());
}
fn wait(condition:impl Fn()->bool){let start=std::time::Instant::now();let context=glib::MainContext::default();while !condition(){while context.pending(){context.iteration(false);}assert!(start.elapsed()<Duration::from_secs(20),"universe GTK callback timed out");std::thread::sleep(Duration::from_millis(5));}while context.pending(){context.iteration(false);}}
fn pump(){let start=std::time::Instant::now();wait(||start.elapsed()>=Duration::from_millis(80));}
fn rpc(client:&Process,op:&str,args:Value)->Value{let result=Rc::new(RefCell::new(None));let out=result.clone();client.rpc(op,args,move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let reply=result.borrow_mut().take().unwrap().unwrap();reply}
fn all_text(widget:&gtk::Widget)->String{if let Ok(view)=widget.clone().downcast::<gtk::TextView>(){let buffer=view.buffer().unwrap();return buffer.text(&buffer.start_iter(),&buffer.end_iter(),true).unwrap_or_default().into();}if let Ok(label)=widget.clone().downcast::<gtk::Label>(){return label.text().into();}widget.clone().downcast::<gtk::Container>().ok().map(|c|c.children().iter().map(all_text).collect::<Vec<_>>().join("\n")).unwrap_or_default()}
fn find_filter(widget:&gtk::Widget)->Option<gtk::Entry>{if let Ok(entry)=widget.clone().downcast::<gtk::Entry>(){if entry.tooltip_text().as_deref()==Some("Filter shared World notes"){return Some(entry);}}widget.clone().downcast::<gtk::Container>().ok().and_then(|c|c.children().iter().find_map(find_filter))}
fn find_view(widget:&gtk::Widget)->Option<gtk::TextView>{widget.clone().downcast::<gtk::TextView>().ok().or_else(||widget.clone().downcast::<gtk::Container>().ok().and_then(|c|c.children().iter().find_map(find_view)))}
fn find_button(widget:&gtk::Widget,name:&str)->Option<gtk::Button>{if let Ok(button)=widget.clone().downcast::<gtk::Button>(){if button.label().as_deref()==Some(name){return Some(button);}}widget.clone().downcast::<gtk::Container>().ok().and_then(|c|c.children().iter().find_map(|w|find_button(w,name)))}

fn find_reference_filter(widget:&gtk::Widget)->Option<gtk::Entry>{if let Ok(entry)=widget.clone().downcast::<gtk::Entry>(){if entry.tooltip_text().as_deref()==Some("Filter shared World notes in references"){return Some(entry);}}widget.clone().downcast::<gtk::Container>().ok().and_then(|c|c.children().iter().find_map(find_reference_filter))}
